import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

model_kernels_source = r'''
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <vector>

// ==================================
// MatMul with bias
// ==================================
__global__ void matmul_kernel(const float* x,
                              const float* w,
                              const float* b,
                              float* out,
                              int B, int inF, int outF) {
    int i = blockIdx.x * blockDim.x + threadIdx.x; // batch index
    int j = blockIdx.y * blockDim.y + threadIdx.y; // out_features index
    if (i < B && j < outF) {
        float val = b[j];
        for (int k = 0; k < inF; k++) {
            val += x[i * inF + k] * w[j * inF + k];
        }
        out[i * outF + j] = val;
    }
}

torch::Tensor matmul_cuda(torch::Tensor x,
                          torch::Tensor w,
                          torch::Tensor b) {
    TORCH_CHECK(x.dim() == 2, "x must be 2D (B, inF)");
    TORCH_CHECK(w.dim() == 2, "w must be 2D (outF, inF)");
    TORCH_CHECK(b.dim() == 1, "b must be 1D (outF)");

    int B = x.size(0);
    int inF = x.size(1);
    int outF = w.size(0);

    auto options = x.options();
    auto out = torch::zeros({B, outF}, options);

    const int BLOCK = 16;
    dim3 block(BLOCK, BLOCK);
    dim3 grid((B + BLOCK - 1) / BLOCK, (outF + BLOCK - 1) / BLOCK);

    matmul_kernel<<<grid, block>>>(x.data_ptr<float>(),
                                   w.data_ptr<float>(),
                                   b.data_ptr<float>(),
                                   out.data_ptr<float>(),
                                   B, inF, outF);
    return out;
}

// ==================================
// MaxPool1D (stride = kernel_size) along last dim
// ==================================
__global__ void maxpool_kernel(const float* in,
                               float* out,
                               int B, int outF, int kernel_size) {
    int i = blockIdx.x * blockDim.x + threadIdx.x; // batch index
    int p = blockIdx.y * blockDim.y + threadIdx.y; // pooled index
    int pooled_size = outF / kernel_size;
    if (i < B && p < pooled_size) {
        float max_val = in[i * outF + p * kernel_size];
        for (int q = 1; q < kernel_size; q++) {
            float val = in[i * outF + p * kernel_size + q];
            if (val > max_val) {
                max_val = val;
            }
        }
        out[i * pooled_size + p] = max_val;
    }
}

torch::Tensor maxpool_cuda(torch::Tensor x, int64_t kernel_size) {
    TORCH_CHECK(x.dim() == 2, "x must be 2D (B, outF)");
    int B = x.size(0);
    int outF = x.size(1);
    int pooled_size = outF / kernel_size;

    auto options = x.options();
    auto out = torch::zeros({B, pooled_size}, options);

    const int BLOCK_X = 16;
    const int BLOCK_Y = 16;

    dim3 block(BLOCK_X, BLOCK_Y);
    dim3 grid((B + BLOCK_X - 1) / BLOCK_X, (pooled_size + BLOCK_Y - 1) / BLOCK_Y);

    maxpool_kernel<<<grid, block>>>(x.data_ptr<float>(),
                                    out.data_ptr<float>(),
                                    B, outF, kernel_size);
    return out;
}

// ==================================
// Sum across last dim, then scale
// ==================================
__global__ void sum_scale_kernel(const float* in,
                                 float* out,
                                 int B, int dimSize,
                                 float scale) {
    int i = blockIdx.x * blockDim.x + threadIdx.x; // batch index
    if (i < B) {
        float s = 0.0;
        for (int j = 0; j < dimSize; j++) {
            s += in[i * dimSize + j];
        }
        out[i] = s * scale;
    }
}

torch::Tensor sum_scale_cuda(torch::Tensor x, float scale_factor) {
    TORCH_CHECK(x.dim() == 2, "x must be 2D (B, pooled_size)");
    int B = x.size(0);
    int dimSize = x.size(1);

    auto options = x.options();
    auto out = torch::zeros({B}, options);

    const int BLOCK = 256;
    int grid = (B + BLOCK - 1) / BLOCK;

    sum_scale_kernel<<<grid, BLOCK>>>(x.data_ptr<float>(),
                                      out.data_ptr<float>(),
                                      B, dimSize,
                                      scale_factor);
    return out;
}
'''

model_kernels_cpp_source = r'''
torch::Tensor matmul_cuda(torch::Tensor x,
                          torch::Tensor w,
                          torch::Tensor b);

torch::Tensor maxpool_cuda(torch::Tensor x, int64_t kernel_size);

torch::Tensor sum_scale_cuda(torch::Tensor x, float scale_factor);
'''

model_kernels = load_inline(
    name="model_kernels",
    cpp_sources=model_kernels_cpp_source,
    cuda_sources=model_kernels_source,
    functions=["matmul_cuda", "maxpool_cuda", "sum_scale_cuda"],
    verbose=False
)

class ModelNew(nn.Module):
    """
    Optimized model that performs matmul, maxpool, sum, and scaling via custom CUDA ops.
    """
    def __init__(self, in_features, out_features, kernel_size, scale_factor):
        super(ModelNew, self).__init__()
        self.in_features = in_features
        self.out_features = out_features
        self.kernel_size = kernel_size
        self.scale_factor = scale_factor
        # Parameters to replace nn.Linear
        self.weight = nn.Parameter(torch.randn(out_features, in_features))
        self.bias = nn.Parameter(torch.randn(out_features))

    def forward(self, x):
        # 1) Custom matmul + bias
        matmul_out = model_kernels.matmul_cuda(x, self.weight, self.bias)
        # 2) Custom 1D maxpool 
        pool_out = model_kernels.maxpool_cuda(matmul_out, self.kernel_size)
        # 3) Sum across last dim, then multiply by scale_factor
        out = model_kernels.sum_scale_cuda(pool_out, self.scale_factor)
        return out
